from mk import *

E(id="bagrut-1984-q3", year=1984, label="1984 שאלה 3", topic="gravitation", sub="grav-law", diff=4,
  stem=r"רדיוסים וצפיפותם של שני כוכבים $A$ ו-$B$ הם: $R_A$, $R_B$ ו-$\rho_A$, $\rho_B$ בהתאמה. הנח כי הכוכבים הומוגניים, דהיינו צפיפותם קבועה. (את התשובות לשאלות הבאות עליך לבטא באמצעות ארבעת הגדלים האלו בלבד.)",
  parts=[
    P("א", r"מהו היחס בין תאוצות הנפילה החופשית על פני שני הכוכבים, $g_A/g_B$?", OPEN, ["principle", "algebra"], [
        S(r"מסת כוכב", r"צפיפות כפול נפח", r"M = \rho \cdot \tfrac{4}{3}\pi R^3"),
        S(r"תאוצת הנפילה", r"חוק הכבידה על פני הכוכב", r"g = \frac{GM}{R^2} = \tfrac{4}{3}\pi G\rho R"),
        S(r"היחס", r"מחלקים", r"\frac{g_A}{g_B} = \frac{\rho_A R_A}{\rho_B R_B}"),
    ], r"$\frac{\rho_A R_A}{\rho_B R_B}$", key=r"ρA·RA/(ρB·RB)"),
    P("ב", r"קרוב לפני כל אחד מהכוכבים סובב לוויין במסלול מעגלי. מהו היחס בין זמני המחזור של שני הלוויינים, $T_A/T_B$?", OPEN, ["principle", "algebra"], [
        S(r"זמן מחזור ליד פני הכוכב", r"רדיוס המסלול ≈ R", r"T = 2\pi\sqrt{\frac{R^3}{GM}} = 2\pi\sqrt{\frac{3}{4\pi G\rho}}"),
        S(r"היחס", r"רק הצפיפות נשארת", r"\frac{T_A}{T_B} = \sqrt{\frac{\rho_B}{\rho_A}}"),
    ], r"$\frac{T_A}{T_B} = \sqrt{\frac{\rho_B}{\rho_A}}$", key=r"√(ρA/ρB)"),
    P("ג", r"מהו היחס בין האנרגיות הכוללות (קינטית + פוטנציאלית) של שני הלוויינים, בהנחה שמסותיהם שוות? (הנח כי האנרגיה הפוטנציאלית שווה לאפס באינסוף.)", OPEN, ["principle", "algebra"], [
        S(r"אנרגיה כוללת", r"לוויין במסלול מעגלי", r"E = -\frac{GMm}{2R} \propto \frac{\rho R^3}{R} = \rho R^2"),
        S(r"היחס", r"מחלקים", r"\frac{E_A}{E_B} = \frac{\rho_A R_A^2}{\rho_B R_B^2}"),
    ], r"$\frac{\rho_A R_A^2}{\rho_B R_B^2}$", key=r"ρA·RA²/(ρB·RB²)"),
    P("ד", r"מפני כל אחד מהכוכבים משלחים טיל אל מחוץ לתחום המשיכה של הכוכב. מהו היחס בין המהירויות ההתחלתיות המינימליות שיש להקנות לטילים? הנח כי לכוכבים אין אטמוספרה.", OPEN, ["principle", "algebra"], [
        S(r"מהירות מילוט", r"אנרגיה כוללת אפס", r"v = \sqrt{\frac{2GM}{R}} \propto \sqrt{\rho R^2} = R\sqrt{\rho}"),
        S(r"היחס", r"מחלקים", r"\frac{v_A}{v_B} = \frac{R_A}{R_B}\sqrt{\frac{\rho_A}{\rho_B}}"),
    ], r"$\frac{R_A}{R_B}\sqrt{\frac{\rho_A}{\rho_B}}$", key=r"(RA/RB)√(ρA/ρB)"),
  ],
  concepts=["חוק הכבידה", "צפיפות ומסה", "זמן מחזור של לוויין נמוך", "אנרגיה של לוויין", "מהירות מילוט"],
  summary=r"השוואה בין שני כוכבים לפי רדיוס וצפיפות: תאוצת נפילה, זמן מחזור, אנרגיה ומהירות מילוט.",
  review='צריך החלטה שלך, בסעיף ב (היחס בין זמני המחזור).\nבדף התשובות: שורש של (צפיפות A חלקי צפיפות B), שזה היחס בין זמן המחזור של B לזה של A.\nאצלי: שאלתי על היחס בין זמן המחזור של A לזה של B, ולכן התשובה הפוכה: שורש של (צפיפות B חלקי צפיפות A).\nמה לבדוק: באיזה סדר אתה רוצה לשאול. אם כמו בדף התשובות, כתוב לי ואהפוך את השאלה.')
